void upnp_event_notify_prepare(struct upnp_event_notify *obj) {
    if (!obj || !obj->subscription || obj->subscription->state != UPNP_SUBSCRIPTION_ACTIVE) {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    const char *service_type = obj->subscription->service_type;
    const char *xml_vars = obj->subscription->xml_vars;

    size_t buffer_size = 256;
    size_t len;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    while (1) {
        len = snprintf(buffer, buffer_size, "NOTIFY * HTTP/1.1\r\n"
                                   "Location: %s/event/%s\r\n"
                                   "NT: upnp:event\r\n"
                                   "NTS: ssdp:alive\r\n"
                                   "SEQ: %d\r\n"
                                   "Service-Type: %s\r\n"
                                   "XML: %s\r\n"
                                   "\r\n",
                                   obj->base_url, obj->service_id,
                                   obj->sequence_number,
                                   service_type, xml_vars);

        if (len < buffer_size) {
            break;
        }

        buffer_size *= 2;
        char *new_buffer = realloc(buffer, buffer_size);
        if (!new_buffer) {
            free(buffer);
            obj->state = UPNP_EVENT_ERROR;
            return;
        }
        buffer = new_buffer;
    }

    obj->message = buffer;
    obj->state = UPNP_EVENT_READY;
}

