        return;
    }

    size_t len = snprintf(NULL, 0, "NOTIFY * HTTP/1.1\r\n"
                                  "Location: %s\r\n"
                                  "NT: upnp:event\r\n"
                                  "NTS: ss:alive\r\n"
                                  "SEQ: %u\r\n"
                                  "Content-Type: text/xml; charset=\"utf-8\"\r\n"
                                  "Content-Length: %zu\r\n"
                                  "\r\n"
                                  "%s",
                          obj->subscription->location,
                          obj->seq,
                          strlen(xml_vars),
                          xml_vars);

    if (len == 0) {
        obj->state = UPNP_EVENT_STATE_ERROR;
        return;
    }

    char *buffer = malloc(len);
    if (!buffer) {
        obj->state = UPNP_EVENT_STATE_ERROR;
        return;
    }

    size_t result = snprintf(buffer, len, "NOTIFY * HTTP/1.1\r\n"
                                       "Location: %s\r\n"
                                       "NT: upnp:event\r\n"
                                       "NTS: ss:alive\r\n"
                                       "SEQ: %u\r\n"
                                       "Content-Type: text/xml; charset=\"utf-8\"\r\n"
                                       "Content-Length: %zu\r\n"
                                       "\r\n"
                                       "%s",
                             obj->subscription->location,
                             obj->seq,
                             strlen(xml_vars),
                             xml_vars);

    if (result >= len) {
        free(buffer);
        buffer = malloc(result + 1); // +1 to be safe
        if (!buffer) {
            obj->state = UPNP_EVENT_STATE_ERROR;
            return;
        }
        snprintf(buffer, result + 1, "NOTIFY * HTTP/1.1\r\n"
                                     "Location: %s\r\n"
                                     "NT: upnp:event\r\n"
                                     "NTS: ss:alive\r\n"
                                     "SEQ: %u\r\n"
                                     "Content-Type: text/xml; charset=\"utf-8\"\r\n"
                                     "Content-Length: %zu\r\n"
                                     "\r\n"
                                     "%s",
                 obj->subscription->location,
                 obj->seq,
                 strlen(xml_vars),
                 xml_vars);
    }

    free(obj->buffer);
    obj->buffer = buffer;
    obj->buffer_len = len;
    obj->state = UPNP_EVENT_STATE_READY;
