void upnp_event_prepare_notify(struct upnp_event_notify *obj) {
    if (!obj->subscription || obj->subscription->state != UPNP_SUB_ACTIVE) {
        obj->state = UPNP_EVENT_ERR;
        return;
    }

    const char *xml_vars = NULL;
    if (obj->subscription->service_type == UPNP_SERVICE_TYPE_1) {
        xml_vars = obj->subscription->xml_vars_1;
    } else if (obj->subscription->service_type == UPNP_SERVICE_TYPE_2) {
        xml_vars = obj->subscription->xml_vars_2;
    }

    if (!xml_vars) {
        obj->state = UPNP_EVENT_ERR;
        return;
    }

    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        obj->state = UPNP_EVENT_ERR;
        return;
    }

    int len;
    do {
        len = snprintf(buffer, buffer_size, "NOTIFY * HTTP/1.1\r\n"
                       "Location: %s\r\n"
                       "NT: %s\r\n"
                       "NTS: ss:renewal\r\n"
                       "SID: %s\r\n"
                       "SEQ: %d\r\n"
                       "Content-Type: text/xml\r\n"
                       "\r\n"
                       "<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n"
                       "<e:propertyset xmlns:e=\"urn:schemas-upnp-org:event-1-0\">\r\n"
                       "%s\r\n"
                       "</e:propertyset>",
                       obj->location,
                       obj->subscription->service_type_str,
                       obj->subscription->sid,
                       obj->sequence,
                       xml_vars);
        if (len < 0) {
            free(buffer);
            obj->state = UPNP_EVENT_ERR;
            return;
        }

        if (len >= (int)buffer_size) {
            buffer_size = len + 1;
            char *new_buffer = realloc(buffer, buffer_size);
            if (!new_buffer) {
                free(buffer);
                obj->state = UPNP_EVENT_ERR;
                return;
            }
            buffer = new_buffer;
        }
    } while (len >= (int)buffer_size);

    obj->message = buffer;
    obj->message_length = len;
    obj->state = UPNP_EVENT_READY;
}

